import java.util.Scanner;

public class Main {
    public static long mod_pow(long base, long exp) {
        final long MOD = 1000000007;
        long result = 1;
        for (; exp > 0; exp--) {
            result = (result * base) % MOD;
        }
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long base = sc.nextLong();
        long exponent = sc.nextLong();
        long result_power = 1;

        if (exponent == 0) {
            result_power = base - 1;
        } else if (exponent == 1) {
            result_power = base;
        } else {
            long temp = exponent;
            long cycle_length = 1;
            while (temp != 1) {
                temp = (temp * base) % base;
                cycle_length++;
            }
            result_power = (base - 1) / cycle_length;
        }

        System.out.println(mod_pow(base, result_power));
        sc.close();
    }
}
